insert into public.quiz_workspace(id,data) values(1,$seed${"version": 1, "title": "Cùng khám phá giáo lý", "types": [{"id": "single", "label": "ABCD", "engine": "single"}, {"id": "boolean", "label": "Đúng / Sai", "engine": "boolean"}, {"id": "fill", "label": "Điền từ", "engine": "fill"}, {"id": "multiple", "label": "Nhiều đáp án", "engine": "multiple"}, {"id": "match", "label": "Nối hai cột", "engine": "match"}, {"id": "order", "label": "Sắp xếp thứ tự", "engine": "order"}, {"id": "short", "label": "Trả lời ngắn", "engine": "short"}], "questions": [{"id": "demo-single", "type": "single", "seconds": 30, "enabled": true, "prompt": "Trong một năm, lễ nào mừng Chúa Giêsu sống lại?", "options": ["Lễ Giáng Sinh", "Lễ Phục Sinh", "Lễ Hiển Linh", "Lễ Các Thánh"], "correct": [1], "explanation": "Lễ Phục Sinh mừng Chúa Giêsu sống lại. Đây là câu hỏi minh họa; hãy biên soạn nội dung phù hợp với buổi thi của bạn."}, {"id": "demo-boolean", "type": "boolean", "seconds": 20, "enabled": true, "prompt": "Kinh Lạy Cha là lời kinh Chúa Giêsu dạy các môn đệ.", "answer": true, "explanation": "Đáp án: Đúng."}, {"id": "demo-fill", "type": "fill", "seconds": 30, "enabled": true, "prompt": "Hoàn thành lời kinh sau.", "template": "Lạy Cha chúng con ở trên {{…}}, chúng con nguyện danh Cha cả {{…}}.", "answers": ["trời", "sáng"], "explanation": "Hai từ cần điền lần lượt là “trời” và “sáng”."}, {"id": "demo-multiple", "type": "multiple", "seconds": 45, "enabled": true, "prompt": "Chọn những tên thuộc bốn sách Tin Mừng.", "options": ["Mátthêu", "Máccô", "Luca", "Gioan", "Sáng Thế"], "correct": [0, 1, 2, 3], "explanation": "Bốn sách Tin Mừng mang tên Mátthêu, Máccô, Luca và Gioan."}, {"id": "demo-match", "type": "match", "seconds": 45, "enabled": true, "prompt": "Nối mỗi ngày lễ với ý nghĩa tương ứng.", "pairs": [{"left": "Lễ Giáng Sinh", "right": "Chúa Giêsu giáng sinh"}, {"left": "Lễ Phục Sinh", "right": "Chúa Giêsu sống lại"}, {"left": "Lễ Hiện Xuống", "right": "Chúa Thánh Thần hiện xuống"}], "explanation": "Mỗi số ở cột trái được ghép với một chữ cái ở cột phải."}, {"id": "demo-order", "type": "order", "seconds": 45, "enabled": true, "prompt": "Sắp xếp các biến cố sau theo thứ tự thời gian.", "items": ["Chúa Giêsu giáng sinh", "Chúa Giêsu chịu phép rửa", "Chúa Giêsu chịu chết", "Chúa Giêsu sống lại"], "explanation": "Thứ tự được hiển thị từ biến cố diễn ra trước đến biến cố diễn ra sau."}, {"id": "demo-short", "type": "short", "seconds": 30, "enabled": true, "prompt": "Mẹ của Chúa Giêsu có tên là gì?", "answer": "Maria", "explanation": "Đức Maria là Mẹ của Chúa Giêsu."}]}$seed$::jsonb) on conflict(id) do nothing;
insert into public.quiz_public(id,data) select id,data from public.quiz_workspace where id=1 on conflict(id) do nothing;
